    vstr_at M' ot x' -> 1 <= PM.vs_size x' <= 21 -> PQATSS.ts_text RSEGS M' ot x' -> PQATSS.ws1_postA len x x' ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    PMSP.credit_keep cr cr' (POT x) (POT x') ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI (PM.vs_own x' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

