Definition ccls (b : Z) : Prop := b = 45 \/ 48 <= b <= 57.
Definition strC (Mx : mem) (q n : Z) : Prop := forall i, 0 <= i < n -> exists b, L5.u8_at RSEGS Mx (q + i) b /\ ccls b.
Definition ystrC (Mx : mem) (y : PM.vstr) : Prop := strC Mx (PM.vs_data ot y) (PM.vs_size y).
