Lemma FINX M5 model5 LK5 Aw5 cr5 (y : PM.vstr) (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) :
  GM (PM.vs_own y) M5 model5 LK5 Aw5 cr5 -> vstr_at M5 ot y -> 1 <= PM.vs_size y <= 21 -> PQATSS.ws1_postA len x y -> ystrC M5 y ->
