  msteps RSEGS (L5SAR.st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (L5SAR.st fx9 R9 RET M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (F + 0 <= i < F + 0 + 8) -> ~ (F / 8 + 2147450880 + 0 <= i < F / 8 + 2147450880 + 0 + 32) -> ~ (fl + 0 <= i < fl + 0 + 1) ->
      M9v (Z_to_bv 64 i) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 i)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  getr R9 (reg 3) = getr R (reg 3) -> getr R9 (reg 4) = getr R (reg 4) ->
  getr R9 (reg 1) = Z_to_bv 64 (bvu (getr R (reg 1))) -> getr R9 (reg 2) = Z_to_bv 64 sp ->
  getr R9 (reg 8) = Z_to_bv 64 (bvu (getr R (reg 8))) -> getr R9 (reg 9) = Z_to_bv 64 (bvu (getr R (reg 9))) ->
  getr R9 (reg 18) = Z_to_bv 64 (bvu (getr R (reg 18))) -> getr R9 (reg 19) = Z_to_bv 64 (bvu (getr R (reg 19))) ->
  getr R9 (reg 20) = Z_to_bv 64 (bvu (getr R (reg 20))) -> getr R9 (reg 21) = Z_to_bv 64 (bvu (getr R (reg 21))) ->
  getr R9 (reg 22) = Z_to_bv 64 (bvu (getr R (reg 22))) -> getr R9 (reg 23) = Z_to_bv 64 (bvu (getr R (reg 23))) ->
  getr R9 (reg 24) = Z_to_bv 64 (bvu (getr R (reg 24))) -> getr R9 (reg 25) = Z_to_bv 64 (bvu (getr R (reg 25))) ->
  getr R9 (reg 26) = Z_to_bv 64 (bvu (getr R (reg 26))) -> getr R9 (reg 27) = Z_to_bv 64 (bvu (getr R (reg 27))) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
