Lemma L_Zt My modely LKy Awy cry (y : PM.vstr) (fbv : Z) (fx5 : FPState) R5 :
  GM (PM.vs_own y) My modely LKy Awy cry -> vstr_at My ot y -> 1 <= PM.vs_size y <= 21 -> PQATSS.ws1_postA len x y -> ystrC My y ->
  PMSP.credit_keep cr cry (POT x) (POT y) ->
  REGSP R5 -> getr R5 (reg 19) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 22) = Z_to_bv 64 F -> getr R5 (reg 23) = Z_to_bv 64 F ->
  getr R5 (reg 24) = Z_to_bv 64 (F + 32) ->
  L5.u8_at RSEGS My (F + 32) fbv -> 0 <= fbv <= 255 -> Z.testbit fbv 0 = false ->
