  L5.u8_at RSEGS Mx (spc + 88) 0 /\ L5.u8_at RSEGS Mx (F + 96) fbr /\ L5.u8_at RSEGS Mx (F + 32) fbv
  /\ 0 <= fbr <= 255 /\ Z.testbit fbr 0 = false /\ 0 <= fbv <= 255 /\ Z.testbit fbv 0 = false.
