Lemma TLF_keep (Ma Mb : mem) fbr fbv :
  (forall a, spc + 88 <= a < spc + 89 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) -> (forall a, F + 32 <= a < F + 128 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
