(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma PBCALL My modely LKy Awy cry (c n p ch ra : Z) (fx5 : FPState) R5 :
  GM [(p, c)] My modely LKy Awy cry -> vstr_at My ot (PM.VLong c n p) -> 0 <= n <= 20 ->
  getr R5 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REGSP R5 ->
  getr R5 (reg 10) = Z_to_bv 64 ot -> getr R5 (reg 11) = Z_to_bv 64 ch -> 0 <= ch < 256 -> strC My p n -> ccls ch ->
  (forall (fx6 : FPState) R6 M6 model6 LK6,
      GM [(p, c)] M6 model6 LK6 Awy cry -> vstr_at M6 ot (PM.VLong c (n + 1) p) -> strC M6 p (n + 1) -> regs_preserved R5 R6 -> REGSP R6 ->
      (forall a, spc <= a < sp -> M6 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + 128 -> M6 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + 32 -> M6 (Z_to_bv 64 a) = My (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 ra M6 model6) K) ->
