  (forall a, spc <= a < sp -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) /\ (forall a, F + 32 <= a < F + 128 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, F / 8 + SB <= a < F / 8 + SB + 32 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)).
