  REGSP R5 -> getr R5 (reg 10) = Z_to_bv 64 j -> getr R5 (reg 18) = Z_to_bv 64 10 -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 22) = Z_to_bv 64 M10 ->
  getr R5 (reg 23) = Z_to_bv 64 (F + 104) -> getr R5 (reg 24) = Z_to_bv 64 rv -> getr R5 (reg 25) = Z_to_bv 64 18 -> getr R5 (reg 26) = Z_to_bv 64 18446744073709551615 -> getr R5 (reg 27) = Z_to_bv 64 1 ->
