Lemma FPIECE My modely LKy Awy cry (c n p fbq : Z) (ql : nat) (q0 q1 fbr : Z) (rl : nat) (r0 r1 : Z) (fx5 : FPState) R5 :
  GM [(p, c)] My modely LKy Awy cry -> FRAM My -> VRF My fbq ql q0 q1 fbr rl r0 r1 -> (ql <= 1)%nat -> (rl <= 1)%nat ->
  REGSP R5 -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) -> getr R5 (reg 23) = Z_to_bv 64 (F + 104) -> getr R5 (reg 24) = Z_to_bv 64 (F + 32) ->
  (forall (fx8 : FPState) R8 model8,
      GM [(p, c)] My model8 LKy Awy cry -> REGSP R8 -> (forall k, In k [18; 21; 22; 23; 25]%nat -> getr R8 (reg k) = getr R5 (reg k)) ->
      getr R8 (reg 10) = Z_to_bv 64 0 -> getr R8 (reg 24) = Z_to_bv 64 (if Nat.eqb rl 0 then 0 else r0) ->
      getr R8 (reg 26) = Z_to_bv 64 ((-1) * Z.of_nat ql) -> getr R8 (reg 27) = Z_to_bv 64 (Z.of_nat ql) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx8 R8 DIGIT My model8) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 RA_DIV My modely) K.
Proof.
