(* [comment removed for export] *)
Definition FRAMD (Mx : mem) : Prop :=
  L5.u64_at RSEGS Mx (spc + 8) o /\ L5.u64_at RSEGS Mx (spc + 16) F /\ L5.u64_at RSEGS Mx (spc + 24) F /\ L5.u64_at RSEGS Mx (spc + 32) (F / 8 + 2147450880)
  /\ L5.u64_at RSEGS Mx (spc + 40) 2147450880.
