(* [comment removed for export] *)
Lemma L_Z My modely LKy Awy cry (y : PM.vstr) (fbv : Z) (fx5 : FPState) R5 :
  GM (PM.vs_own y) My modely LKy Awy cry -> vstr_at My ot y -> PM.vs_size y = 0 ->
  (forall y', PM.vs_own y' = PM.vs_own y -> (match y, y' with PM.VShort _, PM.VShort _ => True | PM.VLong c _ p, PM.VLong c' _ p' => c' = c /\ p' = p | _, _ => False end) -> PQATSS.ws1_postA len x y') ->
  PMSP.credit_keep cr cry (POT x) (POT y) ->
  L5.u8_at RSEGS My (F + 32) fbv -> 0 <= fbv <= 255 -> Z.testbit fbv 0 = false ->
  REGSP R5 -> getr R5 (reg 18) = Z_to_bv 64 0 -> getr R5 (reg 19) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 21) = Z_to_bv 64 2147450880 ->
  getr R5 (reg 22) = Z_to_bv 64 F -> getr R5 (reg 23) = Z_to_bv 64 F -> getr R5 (reg 24) = Z_to_bv 64 (F + 32) -> getr R5 (reg 25) = Z_to_bv 64 o ->
